orm:rotate(-2deg);border:1px solid #183d3e14}.photo:nth-child(2){transform:rotate(2deg)}.photo:nth-child(3){transform:rotate(-1deg)}.scene{height:195px;background-image:var(--art);background-size:300% 100%;background-position:0% center}.photo:nth-child(2) .scene{background-position:50% center}.photo:nth-child(3) .scene{background-position:100% center}.caption{display:flex;justify-content:space-between;gap:8px;padding:12px 6px 0;font-size:17px}.caption small{font:11px 'Trebuchet MS',sans-serif;letter-spacing:1px;padding-top:5px}.board{background:var(--ink);color:var(--paper);padding:28px;border-radius:6px}.bar{display:flex;justify-content:space-between;gap:20px;align-items:center;border-bottom:1px solid #f6f0df44;padding-bottom:20px;margin-bottom:24px}h2{font-size:28px;line-height:1.2;font-weight:400;margin:0 0 8px}.budget{white-space:nowrap;font:12px 'Trebuchet MS',sans-serif;text-align:right}.budget strong{font:32px Georgia,serif;color:var(--gold)}.budget progress{width:110px;height:6px;display:block;margin:6px 0 0;accent-color:var(--gold)}.collections{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.collection{background:#ffffff09;padding:18px;border:1px solid #ffffff22}.collection h3{font-size:21px;font-weight:400;margin:0 0 5px}.original{font:12px 'Trebuchet MS',sans-serif;color:#e4d7b9;margin:12px 0}.places{display:grid;gap:8px}.place{width:100%;text-align:left;border-color:#f6f0df66;color:var(--paper);display:flex;align-items:center;justify-content:space-between;gap:10px;font-size:12px;padding:10px}.place span:last-child{color:var(--gold);white-space:nowrap}.place:hover{background:#ffffff12}.place[aria-pressed=true]{background:var(--gold);color:var(--ink);border-color:var(--gold)}.place[aria-pressed=true] span:last-child{color:var(--ink)}.checks{font:12px/1.8 'Trebuchet MS',sans-serif;margin:15px 0 0;color:#d8d9ca}.checks .yes{color:var(--gold)}.board-note{color:#e4d7b9;font:12px/1.5 'Trebuchet MS',sans-serif;margin:20px 0 0;min-height:18px}.legend{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;margin:25px 0 40px}.legend h3{font:700 13px 'Trebuchet MS',sans-serif;margin:0 0 7px}.legend p{font:13px/1.5 'Trebuchet MS',sans-serif;margin:0;color:var(--muted)}.testhead{display:flex;justify-content:space-between;align-items:center;gap:16px}.incidents{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:20px 0}.incident{text-align:left;background:#fff8e9;padding:15px}.incident b{display:block;font:25px Georgia,serif;margin-bottom:10px}.incident[aria-pressed=true]{background:var(--coral);color:#fff9ee;border-color:var(--coral)}.report{border:1px solid #183d3e55;padding:26px;background:#fffaf0;min-height:170px}.report h3{font-size:25px;font-weight:400;margin:0 0 10px}.restores{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:22px}.restore{border-top:3px solid var(--ink);padding-top:12px;font:13px/1.6 'Trebuchet MS',sans-serif}.restore.lost{border-color:var(--coral);color:var(--coral)}.restore strong{display:block;font-size:15px}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:24px}.primary{background:var(--ink);color:var(--paper)}.primary:hover{background:#285658}.lesson{margin:40px 0 25px;display:grid;grid-template-columns:180px 1fr;gap:24px;border-top:1px solid #183d3e55;padding-top:28px}.numbers{font-size:49px;letter-spacing:3px;color:var(--coral)}.lesson p{margin:0 0 10px}.footer{border-top:1px solid #183d3e55;padding-top:20px;font:12px/1.8 'Trebuchet MS',sans-serif}.footer p{max-width:760px}.noscript{padding:20px;background:var(--gold)}@media(max-width:760px){.shell{padding:22px 18px}.hero{grid-template-columns:1fr;gap:15px;padding:30px 0}.hero aside{padding-left:18px}h1{letter-spacing:-2px}.photos{gap:10px}.scene{height:135px}.caption{font-size:13px;display:block;padding:8px 0 0}.caption small{display:block}.board{padding:18px}.collections{grid-template-columns:1fr}.collection{padding:16px}.places{grid-template-columns:1fr 1fr}.legend{grid-template-columns:1fr 1fr}.incidents{grid-template-columns:1fr 1fr}.restores{grid-template-columns:1fr}.lesson{grid-template-columns:1fr;gap:10px}.testhead{align-items:flex-start}.bar h2{font-size:25px}.top{font-size:10px}.photo{padding:6px 6px 12px}}@media(max-width:380px){.places{grid-template-columns:1fr}.scene{height:110px}}@media(prefers-reduced-motion:reduce){*{transition:none!important;scroll-behavior:auto!important}}@media print{body{background:white}.top,.photos,.board,.legend,.incidents,.actions,.testhead button{display:none}.hero{padding:10px 0;display:block}h1{font-size:40px}.report{break-inside:avoid}.shell{padding:0}.lesson{margin:20px 0}.footer{font-size:10px}}
